                        stack.append((ny,nx))
            components.append(cells)
    for cells in components:
        r0 = min(r for r,c in cells); r1 = max(r for r,c in cells)
        c0 = min(c for r,c in cells); c1 = max(c for r,c in cells)
        top = {c for r,c in cells if r == r0}
        # Complete the open top and hollow interior in the frame.
        for c in range(c0, c1 + 1):
            if grid[r0][c] == 0:
                out[r0][c] = 2
        for r in range(r0 + 1, r1):
            for c in range(c0 + 1, c1):
                if grid[r][c] == 0:
                    out[r][c] = 2
        # Extend the opening outward toward the side with the longer top rim.
        opening = [c for c in range(c0, c1 + 1) if c not in top]
